import sys


def perimeter(a, b):
    # Perimeter of a rectangle (0,0)-(a,b) in the axis-aligned grid.
    # Returns 2*(a+b) vertices in cyclic order.
    pts = [(0, 0)]
    for x in range(1, a + 1):
        pts.append((x, 0))
    for y in range(1, b + 1):
        pts.append((a, y))
    for x in range(a - 1, -1, -1):
        pts.append((x, b))
    for y in range(b - 1, 0, -1):
        pts.append((0, y))
    return pts


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1
    out = []
    OFF = 10**6

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        # Necessary conditions:
        # - R must be even.
        # - If R == 0, then B must be even.
        if R + B < 2 or (R % 2 == 1) or (R == 0 and B % 2 == 1):
            out.append("No")
            continue

        if R == 0:
            # All blue, B is even.
            if B == 2:
                pts = [(0, 0), (1, 1)]
            else:
                k = B // 2
                # Build a cycle in the diagonal grid.
                # Use scaled coordinates (x,y), then map to (x+y, x-y).
                pts = perimeter(1, k - 1)
                pts = [(x + y, x - y) for x, y in pts]

            out.append("Yes")
            for x, y in pts:
                out.append(f"B {x + OFF} {y + OFF}")

        elif B == 0:
            # All red, R is even.
            if R == 2:
                pts = [(0, 0), (1, 0)]
            else:
                m = R // 2
                pts = perimeter(1, m - 1)

            out.append("Yes")
            for x, y in pts:
                out.append(f"R {x + OFF} {y + OFF}")

        else:
            # Mixed case: R > 0, R is even, B >= 1.
            red = []
            blue = []

            if B % 2 == 1:
                # Endpoints: red start A=(0,0), blue start D=(1,1).
                m = R // 2

                # Red path of length R from (0,0) to (1,1).
                for y in range(m + 1):
                    red.append((0, y))
                red.append((1, m))
                for y in range(m - 1, 0, -1):
                    red.append((1, y))
                red.pop()  # remove (1,1), which will be the first blue piece

                # Blue path of length B from (1,1) to (0,0).
                k = B // 2
                for y in range(k + 1):
                    blue.append((1 + y, 1 - y))
                for y in range(k, -1, -1):
                    blue.append((y, -y))
                blue.pop()  # remove (0,0), which is the first red piece

            else:
                # Endpoints: red start A=(0,0), blue start D=(2,0).
                m = R // 2
                a = m - 1

                # Red path of length R from (0,0) to (2,0).
                for y in range(a + 1):
                    red.append((0, y))
                red.append((1, a))
                red.append((2, a))
                for y in range(a - 1, -1, -1):
                    red.append((2, y))
                red.pop()  # remove (2,0), which will be the first blue piece

                # Blue path of length B from (2,0) to (0,0).
                k = B // 2
                for y in range(1, k + 1):
                    blue.append((1 + y, 1 - y))
                for y in range(k, -1, -1):
                    blue.append((y, -y))
                blue.pop()  # remove (0,0), which is the first red piece

            out.append("Yes")
            for x, y in red:
                out.append(f"R {x + OFF} {y + OFF}")
            for x, y in blue:
                out.append(f"B {x + OFF} {y + OFF}")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()

