import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    M = N * K

    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(M + 1)]
    idx = 2
    for _ in range(M - 1):
        u = data[idx]
        v = data[idx + 1]
        idx += 2
        adj[u].append(v)
        adj[v].append(u)
    del data

    # Root the tree at 1.
    parent = [-1] * (M + 1)
    parent[1] = 0
    order = []
    stack = [1]

    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if parent[to] == -1:
                parent[to] = v
                stack.append(to)

    # Subtree sizes.
    sub = [1] * (M + 1)
    for v in reversed(order):
        if v != 1:
            sub[parent[v]] += sub[v]

    # Edge (v, parent[v]) must be used iff sub[v] % K != 0.
    selected = bytearray(M + 1)
    for v in range(2, M + 1):
        if sub[v] % K != 0:
            selected[v] = 1

    visited = bytearray(M + 1)

    # Check each connected component of selected edges.
    for s in range(1, M + 1):
        if visited[s]:
            continue

        cnt = 0
        stack = [s]
        visited[s] = 1

        while stack:
            v = stack.pop()
            cnt += 1

            if cnt > K:
                print("No")
                return

            deg = 0
            for to in adj[v]:
                if parent[to] == v:
                    sel = selected[to]
                else:
                    sel = selected[v]

                if sel:
                    deg += 1
                    if deg > 2:
                        print("No")
                        return

                    if not visited[to]:
                        visited[to] = 1
                        stack.append(to)

        if cnt != K:
            print("No")
            return

    print("Yes")

if __name__ == "__main__":
    solve()
